import {rotations} from './core.js';
export function mountDecision(c,f){
c.innerHTML='<section class="decision-world"><small>TU PRÓXIMA CAMPAÑA EMPIEZA AQUÍ</small><h2>Imagina lo que tu tierra<br>puede ser.</h2><p>Explora opciones. Cambia el agua y el tiempo. Entiende qué puedes considerar antes de sembrar.</p><div class="decision-orchard" aria-hidden="true">🌳 🌳 🌳<br>🌱 🌱 🌱 🌱 🌱</div><p><strong>Frutales establecidos:</strong> conserva tus árboles mientras evalúas manejo, cobertura o una reconversión a largo plazo con un técnico. Mango y limón no se rotan cada campaña.</p></section><div class="card"><h2>¿Y si cambiamos las condiciones?</h2><p>Escenario ilustrativo: estos controles no son mediciones de tu finca.</p><form class="toolbar" id="decision-controls"><label>💧 Agua disponible<select name="water"><option value="1">Poca</option><option value="2">Intermedia</option><option value="3">Abundante</option></select></label><label>📅 Tiempo disponible<input name="horizon" type="range" min="1" max="24"><output id="decision-months"></output></label><label>🌱 ¿Tienes un lote para cultivos anuales?<select name="annual"><option value="false">No, solo frutales</option><option value="true">Sí, un lote separado</option></select></label><label>🎯 Mi prioridad<select name="priority"><option value="agua">Usar menos agua</option><option value="ciclo">Terminar antes</option></select></label></form></div><div id="decision-results" aria-live="polite"></div><div class="notice">Comparación experimental: duración y demanda de agua son supuestos del prototipo. No predice cosechas ni ganancias. Antes de elegir faltan suelo, agua real, costos, mercado e historial de cultivos.</div>';
const form=c.querySelector('form');for(const k of ['water','horizon','annual','priority'])form.elements[k].value=String(f[k]);if(!form.elements.priority.value)form.elements.priority.value='agua';
function draw(){const input={...f,water:Number(form.elements.water.value),horizon:Number(form.elements.horizon.value),annual:form.elements.annual.value==='true',priority:form.elements.priority.value};c.querySelector('output').textContent=input.horizon+' meses';const rows=rotations(input);c.querySelector('#decision-results').innerHTML='<h2>Tu abanico de posibilidades</h2><p>'+(input.annual?'Toca una opción para descubrir su recorrido.':'Para estas rotaciones necesitas un lote anual separado. Tus árboles permanecen en su lugar.')+'</p><div class="decision-options">'+rows.map((r,i)=>'<article class="decision-option"><span class="decision-crop" aria-hidden="true">'+(r.name.startsWith('Maíz')?'🌽':r.name.startsWith('Yuca')?'🌿':'🌱')+'</span><small>'+(!r.reasons.length?'OPCIÓN PARA REVISAR':'POR AHORA NO ENCAJA')+'</small><h3>'+r.name+'</h3><p>💧 Demanda '+['','baja','media','alta'][r.water]+' · 📅 '+r.months+' meses</p><p>'+(!r.reasons.length?'Cumple el agua, el tiempo y el lote de este escenario.':r.reasons.join(' · '))+'</p><details><summary>Ver el camino →</summary><ol>'+r.name.split(' → ').map(s=>'<li>'+s+'</li>').join('')+'</ol><p>El descanso forma parte del supuesto de duración. Las fechas concretas deben validarse en tu zona.</p><strong>Antes de decidir</strong><p>Confirma suelo y riego con tu técnico, y quién comprará tu producción.</p></details></article>').join('')+'</div>';}
form.oninput=draw;form.onsubmit=e=>e.preventDefault();draw();}
